16	export const RANDOM_SELECTION_KEY = '__RANDOM__';
17	
18	export interface SubjectTelemetry {
19	  totalFemales: number;
20	  totalMales: number;
21	  visibleFemales: number;
22	  visibleMales: number;
23	  totalVisible: number;
