28	export interface TriggerState {
29	  app: App | null;
30	  isLoading: boolean;
31	  isSaving: boolean;
32	  isTemplatesLoading: boolean;
33	
34	  // Data-Driven Hierarchies & Components
35	  folders: ComponentFolderNode[]; // Standard standalone components (Components/)
36	  matrixDomains: MatrixDomainNode[]; // Dynamic two-tier hierarchical domains (Matrices/)
37	
38	  // Conditions Physics Registry & Conflict Resolution
39	  conditions: Record<string, ConditionEntry>;
40	  ignoredConditionIds: string[];
41	  conditionConflicts: ConditionConflict[];
42	
43	  selections: Record<string, string | null>; // relPath -> selectedKey | '__RANDOM__' (null = blank)
44	  randomPools: Record<string, string[]>; // relPath -> array of option keys allowed when rolling random
45	
46	  // Dynamic Data-Driven Matrix Domain States (domainId -> array of active state IDs)
47	  matrixBaseStates: Record<string, string[]>; // Level 1: Constant Ground Anchors per domain
48	  matrixUnlockedPools: Record<string, string[]>; // Level 2: Unlocked Dynamic Pools per domain
49	
50	  // Universal Gacha-Lock Registry & Template Niche Unlocking Keys
51	  globalLockedKeys: Record<string, boolean>; // relPath:key -> isLocked (locked across all normal templates)
52	  unlockLockedAll: boolean; // Master override to unlock all niche locked options for active template
53	  unlockKeys: string[]; // Specific domain lock keys unlocked by active template (e.g. ['niche', 'extreme', 'harem'])
54	  unlockedOptionKeys: string[]; // Specific option paths unlocked
55	
56	  // Template-Scoped Component Lock Registry
57	  // Lock applies to this template only: { relPath: lockedKey } -> pins a specific option when in random mode
58	  // Note: These locks bind the rolled option locally; if a component rolls differently, the locked result stays pinned.
59	  perTemplateLockSelections?: Record<string, string>; // Template-level pinned random rolls
60	
61	  // Local Locked Random Rolls Registry (Component in random mode with a pinned roll for the active workspace/session)
62	  lockedRandomSelections: Record<string, string>; // relPath -> lockedOptionKey
63	
64	  resolvedSelections: Record<string, string | null>; // relPath -> actually chosen key for current generation
65	  randomCount: number; // number of components set to RANDOM_SELECTION_KEY
66	  rollCount: number; // incremented on each generation / roll
67	
68	  // Template State
69	  templates: HazardTemplate[];
70	  activeTemplate: HazardTemplate | null;
71	
72	  // Computed State
73	  telemetry: SubjectTelemetry;
74	  activeKeywords: string[];
75	  activeExclusions: string[];
76	  compiledPrompt: string;
77	  tokenCount: number;
78	
79	  // Actions
80	  init: (app: App) => Promise<void>;
81	  reload: () => Promise<void>;
82	  selectOption: (relPath: string, key: string | null) => void;
83	  rerollRandoms: () => void;
84	  randomizeAll: () => void;
85	  clearAllSelections: () => void;
86	
87	  // Condition Actions
88	  ignoreCondition: (condId: string) => void;
89	  unignoreCondition: (condId: string) => void;
90	  clearIgnoredConditions: () => void;
91	
92	  // Local Locked Random Roll Actions
93	  lockRandomOption: (relPath: string, key?: string) => void;
94	  unlockRandomOption: (relPath: string) => void;
95	  unlockAllRandomOptions: () => void;
96	  toggleLockRandomOption: (relPath: string) => void;
97	
98	  // Random Pool Granular Actions
99	  toggleRandomOption: (relPath: string, optionKey: string, allKeys: string[]) => void;
100	  selectAllForRandom: (relPath: string, allKeys: string[]) => void;
101	  deselectAllForRandom: (relPath: string) => void;
102	
103	  // Dynamic Data-Driven Matrix Domain Actions
104	  toggleMatrixBaseState: (domainId: string, stateId: string) => void;
105	  selectAllMatrixBaseStates: (domainId: string) => void;
106	  clearMatrixBaseStates: (domainId: string) => void;
107	
108	  toggleMatrixUnlockedPool: (domainId: string, stateId: string) => void;
109	  selectAllMatrixUnlockedPools: (domainId: string) => void;
110	  clearMatrixUnlockedPools: (domainId: string) => void;
111	  clearMatrixDomain: (domainId: string) => void;
