122	    name: string,
123	    description?: string,
124	    category?: string,
125	    tags?: string[],
126	    unlockLockedAll?: boolean,
127	    unlockKeys?: string[]
128	  ) => Promise<HazardTemplate | null>;
129	  updateActiveTemplate: () => Promise<void>;
130	  applyTemplate: (template: HazardTemplate) => Promise<void>;
131	  deleteTemplate: (template: HazardTemplate) => Promise<void>;
132	  detachActiveTemplate: () => void;
133	
134	  // Template-Scoped Component Lock Actions
135	  // When a template defines `lock: { relPath: optionKey }`, that component's roll is pinned locally for that template.
136	  setTemplateLock: (template: HazardTemplate | null, lockSelections: Record<string, string>) => void;
137	  applyTemplateLockSelections: (templateLock: Record<string, string>) => void;
138	  removeTemplateLockSelection: (relPath: string) => void;
139	}
