195	/**
196	 * Recursively resolves a ComponentEntry's full Tag-Team inheritance lineage.
197	 * Traverses tag_team IDs to inherit:
198	 * 1. Precondition Requirements (Preconditions needed)
199	 * 2. Asserted Impacts / Keywords (State assertions)
200	 * 3. Base prompt tokens (Base building blocks prepended before specific prompts)
201	 * 4. Anti-prompt exclusions
202	 * 5. Subject vector modifications
203	 */
204	export function resolveTagTeamLineage(
205	  entry: ComponentEntry,
206	  lookup: (key: string) => ComponentEntry | undefined
207	): {
208	  allEntries: ComponentEntry[];
209	  combinedRequirements: string[];
210	  combinedImpacts: string[];
211	  combinedExclusions: string[];
212	  combinedPromptTokens: string[];
213	  subjects?: [number, number];
214	} {
215	  const visited = new Set<string>();
216	  const lineage: ComponentEntry[] = [];
217	  const queue: ComponentEntry[] = [entry];
218	
219	  while (queue.length > 0) {
220	    const current = queue.shift()!;
221	    lineage.push(current);
222	
223	    if (Array.isArray(current.tag_team)) {
224	      for (const tagKey of current.tag_team) {
225	        const clean = tagKey.trim();
226	        if (clean && !visited.has(clean)) {
227	          visited.add(clean);
228	          const parentEntry = lookup(clean);
229	          if (parentEntry) {
230	            queue.push(parentEntry);
231	          }
232	        }
233	      }
234	    }
235	  }
236	
237	  const combinedReqSet = new Set<string>();
238	  const combinedImpactSet = new Set<string>();
239	  const combinedExclusionSet = new Set<string>();
240	  let combinedSubjects: [number, number] | undefined = undefined;
241	
242	  // Process lineage in reverse (base blocks first, derived entry last)
243	  const reversedLineage = [...lineage].reverse();
244	  const rawTokensList: string[] = [];
245	
246	  for (const item of reversedLineage) {
247	    // Requirements
248	    const reqs = [
249	      ...(Array.isArray(item.requirement) ? item.requirement : []),
250	      ...(Array.isArray(item.require) ? item.require : []),
251	    ];
252	    reqs.forEach((r) => {
253	      const clean = r.toLowerCase().trim();
254	      if (clean) combinedReqSet.add(clean);
255	    });
256	
257	    // Impacts
258	    const impacts = [
259	      ...(Array.isArray(item.impact) ? item.impact : []),
260	      ...(Array.isArray(item.keywords) ? item.keywords : []),
261	    ];
262	    impacts.forEach((i) => {
263	      const clean = i.toLowerCase().trim();
264	      if (clean) combinedImpactSet.add(clean);
265	    });
266	
267	    // Exclusions / Anti-prompt
268	    const antiTokens = typeof item['anti-prompt'] === 'string'
269	      ? item['anti-prompt'].split(',').map((t) => t.trim()).filter(Boolean)
270	      : Array.isArray(item.exclude)
271	      ? item.exclude
272	      : [];
273	    antiTokens.forEach((e) => {
274	      const clean = e.toLowerCase().trim();
275	      if (clean) combinedExclusionSet.add(clean);
276	    });
277	
278	    // Prompt tokens
279	    if (item.prompt && item.prompt.trim()) {
280	      const expanded = expandInlineChoices(item.prompt);
281	      expanded.split(',').map((t) => t.trim()).filter(Boolean).forEach((t) => rawTokensList.push(t));
282	    }
283	
284	    // Subjects: inherit most specific if defined
285	    if (Array.isArray(item.subjects) && item.subjects.length >= 2) {
286	      combinedSubjects = [item.subjects[0], item.subjects[1]];
287	    }
288	  }
289	
290	  // Filter raw tokens by combined exclusions
291	  const exclusionsLower = Array.from(combinedExclusionSet);
292	  const filteredTokens: string[] = [];
293	  const seen = new Set<string>();
294	
295	  for (const token of rawTokensList) {
296	    const clean = token.toLowerCase();
297	    if (!exclusionsLower.includes(clean) && !seen.has(clean)) {
298	      seen.add(clean);
299	      filteredTokens.push(token);
300	    }
301	  }
302	
303	  return {
304	    allEntries: lineage,
305	    combinedRequirements: Array.from(combinedReqSet),
306	    combinedImpacts: Array.from(combinedImpactSet),
307	    combinedExclusions: Array.from(combinedExclusionSet),
308	    combinedPromptTokens: filteredTokens,
309	    subjects: combinedSubjects,
310	  };
311	}
