13	export class TemplateManager {
14	  /**
15	   * Ensures the data and template folders exist in the vault.
16	   */
17	  public static async ensureFolders(app: App): Promise<void> {
18	    const adapter = app.vault.adapter;
19	    const dataFolder = cleanPath(DATA_FOLDER_PATH);
20	    const templatesFolder = cleanPath(TEMPLATES_FOLDER_PATH);
21	
22	    if (!(await adapter.exists(dataFolder))) {
23	      try {
24	        await adapter.mkdir(dataFolder);
25	      } catch (e) {
26	        console.warn('[TemplateManager] Data folder creation:', e);
27	      }
28	    }
29	
30	    if (!(await adapter.exists(templatesFolder))) {
31	      try {
32	        await adapter.mkdir(templatesFolder);
33	      } catch (e) {
34	        console.warn('[TemplateManager] Templates folder creation:', e);
