39	  /**
40	   * Loads global locked option keys from locked_options.json.
41	   */
42	  public static async loadGlobalLockedKeys(app: App): Promise<Record<string, boolean>> {
43	    const adapter = app.vault.adapter;
44	    const filePath = cleanPath(LOCKED_OPTIONS_FILE_PATH);
45	
46	    try {
47	      if (await adapter.exists(filePath)) {
48	        const raw = await adapter.read(filePath);
49	        const data = JSON.parse(raw);
50	        if (data && typeof data === 'object') {
51	          return data as Record<string, boolean>;
52	        }
53	      }
54	    } catch (err) {
55	      console.warn('[TemplateManager] Error loading locked options:', err);
56	    }
57	    return {};
