60	  /**
61	   * Saves global locked option keys to locked_options.json.
62	   */
63	  public static async saveGlobalLockedKeys(app: App, keys: Record<string, boolean>): Promise<void> {
64	    const adapter = app.vault.adapter;
65	    await this.ensureFolders(app);
66	    const filePath = cleanPath(LOCKED_OPTIONS_FILE_PATH);
67	
68	    try {
